bool Job::PerformAbortReset(bool wait_for_stream_quiescence, bool owner_claimed,
                            bool allow_unready_reconnect) {
    auto& pipe = Pipe::GetInstance();
    if (!owner_claimed && !abort_reset_owner_.TryClaim()) {
        return WaitForAbortReset();
    }

